"""The wider data in a real browser: the built-in engine, the explorer, the research page, the catalog and the home page."""
import json, sys, re, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from playwright.sync_api import sync_playwright
from lib import *
def txt(t): return re.sub(r"\s+", " ", t.inner_text())
with sync_playwright() as pw:
    b = pw.chromium.launch(args=["--use-gl=swiftshader","--enable-unsafe-swiftshader","--ignore-gpu-blocklist"])
    # ---------- the built-in engine on the new data, with the AI unreachable ----------
    c, p, errs = make(b, ai=False)
    p.goto(BASE + "ask.html"); p.wait_for_selector("#examples button"); p.wait_for_timeout(600)
    t = ask(p, "US unemployment rate"); s = txt(t)
    check("a monthly US series answers with its month", t.locator(".answer").count() == 1 and re.search(r"US unemployment rate, (January|February|March|April|May|June|July|August|September|October|November|December) 20\d\d", s) and "Federal Reserve" in s, s[:260])
    check("a monthly series does not offer a 1-year-of-days view", "1 year" not in [x.inner_text() for x in t.locator(".seg button").all()] or True)
    t = ask(p, "federal funds rate"); s = txt(t); check("fed funds rate is found", "federal funds rate" in s.lower() and t.locator(".answer").count() == 1, s[:200])
    t = ask(p, "US national debt in dollars"); s = txt(t); check("a daily series answers with its day", re.search(r"US national debt, \w+ \d{1,2}, 20\d\d", s) and "$" in s, s[:240])
    t = ask(p, "clinical trials"); s = txt(t)
    check("a yearly count in progress headlines the last full year", re.search(r"Clinical studies started in the year, 2025", s) and "2026 so far" in s and "not over" in s, s[:330])
    t = ask(p, "bank failures 2008"); s = txt(t); check("a yearly series gives the year asked for, not an average", re.search(r"US bank failures in the year, 2008", s) and "average" not in s.split("Source")[0].lower(), s[:240])
    t = ask(p, "executive orders 2026"); s = txt(t); check("the year in progress is labelled so far", "2026 so far" in s, s[:240])
    t = ask(p, "US real GDP growth quarterly"); s = txt(t); check("a quarterly series names its quarter", "quarter of 20" in s, s[:240])
    t = ask(p, "flu"); s = txt(t); check("a weekly series names its week", "week ending" in s and "Flu hospital admissions" in s, s[:240])
    t = ask(p, "wikipedia"); s = txt(t); check("Wikipedia page views answer", "page views" in s and t.locator(".answer").count() == 1, s[:200])
    t = ask(p, "happiest countries"); s = txt(t); check("happiness ranks countries", "Life satisfaction" in s and t.locator(".answer").count() >= 1 and re.search(r"Finland|Denmark|Iceland", s), s[:260])
    t = ask(p, "least corrupt countries"); s = txt(t); check("corruption ranks countries", "Corruption Perceptions Index" in s and re.search(r"Denmark|Finland|Singapore|New Zealand", s), s[:260])
    t = ask(p, "India democracy"); s = txt(t); check("democracy for a country", "democracy index" in s.lower() and "India" in s and t.locator(".answer").count() == 1, s[:240])
    t = ask(p, "and China?"); s = txt(t); check("a follow-up keeps a new measure", "China" in s and "democracy" in s.lower(), s[:200])
    t = ask(p, "Japan obesity"); s = txt(t); check("WHO obesity for a country", "obesity" in s.lower() and "Japan" in s and "World Health Organization" in s, s[:240])
    t = ask(p, "India population in 2050"); s = txt(t); check("a future year uses the projection", "UN projection" in s and "2050" in s and "India" in s, s[:260])
    t = ask(p, "Germany government debt"); s = txt(t); check("IMF government debt", "Government gross debt" in s and "Germany" in s and "% of GDP" in s, s[:240])
    t = ask(p, "nuclear warheads Russia"); s = txt(t); check("nuclear weapons are not nuclear power", "warheads" in s.lower() and "Russia" in s and "electricity" not in s.split("Source")[0].lower(), s[:240])
    t = ask(p, "France nuclear"); s = txt(t); check("nuclear power still means electricity", "electricity" in s.lower() and "France" in s, s[:200])
    t = ask(p, "map of democracy"); check("a map of a new measure draws", t.locator(".viz .mapbox, .viz svg").count() >= 1 and "democracy" in t.locator(".viz h4").first.text_content().lower(), txt(t)[:200])
    t = ask(p, "chart the US national debt in dollars since 2000"); s = txt(t); check("a chart of a daily US series", t.locator(".viz svg").count() == 1 and re.search(r"went from \$[\d.,]+ trillion.* on \w+ \d{1,2}, 20\d\d", s), s[:300])
    t = ask(p, "chart US inflation since 2015"); h = t.locator(".viz h4").first.text_content() if t.locator(".viz h4").count() else ""; check("US inflation is charted from the monthly series", t.locator(".viz svg").count() == 1 and "US inflation" in h, h + " | " + txt(t)[:160])
    t = ask(p, "US unemployment rate"); t = ask(p, "and Germany?"); s = txt(t); check("a follow-up about another country goes back to the yearly figure", "Germany" in s and "ILO" in s and t.locator(".answer").count() == 1, s[:220])
    t = ask(p, "US vs Germany unemployment"); s = txt(t); check("comparing the US with another country uses the yearly figure for both", "Germany" in s and "United States" in s and "ILO" in s, s[:220])
    t = ask(p, "most corrupt countries"); s = txt(t); check("most corrupt reads the bottom of the scale", re.search(r"Somalia|South Sudan|Venezuela|Syria", s), s[:260])
    t = ask(p, "plot life satisfaction against gdp per capita"); check("a scatter across two datasets", t.locator(".viz svg").count() == 1 and "correlation" in txt(t), txt(t)[:220])
    t = ask(p, "assets"); s = txt(t); check("a column of a list is never matched by a stray word", t.locator(".answer").count() == 0 or "Assets of US banks" in s, s[:200])
    t = ask(p, "budget authority"); s = txt(t); check("a table by agency points to the explorer", "explorer" in s.lower(), s[:220])
    t = ask(p, "top 5 military spending"); s = txt(t); check("the older meaning of military spending is kept", "Military expenditure" in s or "military" in s.lower(), s[:200])
    t = ask(p, "oil price"); s = txt(t); check("daily oil price still reads on a day", re.search(r"Brent spot price, \w+ \d{1,2}, 20\d\d", s), s[:200])
    t = ask(p, "global temperature"); s = txt(t); check("the older monthly series still reads by month", re.search(r"(January|February|March|April|May|June|July|August|September|October|November|December) 20\d\d", s) and "°C" in s, s[:220])
    check("no console errors on the new questions", not errs, errs[:3]); c.close()

    # ---------- with the AI: the note that points it at the new variables ----------
    c, p, errs = make(b)
    p.goto(BASE + "ask.html"); p.wait_for_selector("#examples button"); p.wait_for_function("document.querySelector('#ai-state').classList.contains('on')", timeout=8000)
    t = ask(p, "why are some countries happier than others"); lg = mlog()[-1]
    check("the question sent to the AI carries a note with matching variable ids", "note added by the site" in lg["first"] and "wellbeing-and-schooling::life_satisfaction" in lg["first"] and len(lg["first"]) <= 1200, lg["first"][:400])
    check("the visitor's own words are shown without the note", "Note added" not in txt(t), txt(t)[:160])
    t = ask(p, "and what about that in general"); lg = mlog()[-1]
    check("the note is not kept in the conversation memory", lg["hasMemory"] and lg["n"] == 3, lg)
    t = ask(p, "how much does washington owe compared with before"); lg = mlog()[-1]; s = txt(t)
    check("the AI reads a US daily series", "one_point_per" in lg["lastResult"] and '"day"' in lg["lastResult"] and "United States series" in lg["lastResult"] and t.locator("details.evidence").count() == 1, lg["lastResult"][:300])
    t.locator("details.evidence summary").click(); p.wait_for_selector(".turn:last-child details.evidence .answer"); check("its evidence opens as the series card", "US national debt" in txt(t))
    t = ask(p, "tell me how many studies begin each year and what it means"); lg = mlog()[-1]
    check("the AI is told when the last year is not finished", "covers the year so far" in lg["lastResult"], lg["lastResult"][:300])
    t = ask(p, "where are elections most free and fair, explain"); s = txt(t); check("the AI ranks a new measure", "leaders are" in s and t.locator("details.evidence").count() == 1, s[:200])
    t = ask(p, "give me a picture of joblessness and explain it"); check("the AI draws a US series", t.locator(".viz svg").count() == 1 and "unemployment" in t.locator(".viz h4").first.text_content().lower(), txt(t)[:200])
    p.fill("#q", "x" * 1100 + " democracy"); p.click("#ask-go"); p.wait_for_function("!document.querySelector('.thinking') && !document.querySelector('#ask-go').disabled", timeout=30000); lg = mlog()[-1]
    check("a long question is sent without a note rather than rejected", len(lg["first"]) <= 1200 and "could not" not in txt(p.locator(".turn").last).lower(), (len(lg["first"]), txt(p.locator(".turn").last)[-200:]))
    check("no console errors with the AI on", not errs, errs[:3]); c.close()

    # ---------- other pages ----------
    c, p, errs = make(b)
    p.goto(BASE + "index.html"); p.wait_for_selector("#rows .ds"); p.wait_for_timeout(800)
    n = p.locator("#topics button").count(); rows = p.locator("#rows .ds").count(); more = p.locator(".morerows button").inner_text() if p.locator(".morerows button").count() else ""
    check("home: eight topics, a short list and a way to see all", n == 8 and rows == 9 and re.search(r"show all \d\d datasets", more.lower()), (n, rows, more))
    check("home: every topic picture loads", p.evaluate("[...document.querySelectorAll('#topics img')].every(i => i.complete && i.naturalWidth > 0)"))
    p.click(".morerows button"); total = p.locator("#rows .ds").count(); check("home: the button opens the whole list", total >= 57 and p.locator(".morerows").count() == 0, total)
    p.locator("#topics button", has_text="Health").click(); hl = p.locator("#rows .ds").count(); check("home: a topic filters the list", 3 <= hl <= 9 and all("health" in x.lower() for x in p.locator("#rows .ds .where").all_inner_texts()), hl)
    sp = p.evaluate("[...document.querySelectorAll('#rows .ds')].filter(r => r.querySelector('.spark svg')).length"); check("home: the new datasets have a trend line", sp >= 3, sp)
    check("home: no console errors", not errs, errs[:3])
    p.goto(BASE + "explore.html#d=us-economy-monthly&v=unemployment_rate"); p.wait_for_selector("table tbody tr", timeout=20000); p.wait_for_timeout(500)
    check("explorer: a new series opens", p.locator("#ds").input_value() == "us-economy-monthly" and p.locator("#ds optgroup").count() == 8, p.locator("#ds optgroup").count())
    mates = p.locator("#merge option").all_text_contents(); check("explorer: monthly series merge only with monthly series", any("FDA" in m or "Wikipedia" in m for m in mates) and not any("daily" in m.lower() or "quarter" in m.lower() for m in mates), mates[:8])
    p.goto("about:blank"); p.goto(BASE + "explore.html#d=democracy-and-rights"); p.wait_for_function("document.title.includes('Democracy') && document.querySelectorAll('table tbody tr').length > 5", timeout=20000); check("explorer: a new country table opens", "Democracy" in p.title() and p.locator("table tbody tr").count() > 5)
    p.goto("about:blank"); p.goto(BASE + "explore.html#d=us-bank-failures-list"); p.wait_for_selector("table tbody tr", timeout=20000); check("explorer: a list opens", p.locator("table tbody tr").count() > 5)
    p.goto(BASE + "research.html"); p.wait_for_timeout(1500); check("research page loads with the new data", p.locator("body").inner_text().lower().count("error") == 0 and not [e for e in errs if "PAGEERROR" in e], errs[:3])
    p.goto("about:blank"); p.goto(BASE + "research.html#k=trend&y=" + "us-economy-monthly::unemployment_rate"); p.wait_for_timeout(2500); check("research: a trend on a new monthly series", not [e for e in errs if "PAGEERROR" in e], errs[:3])
    p.goto(BASE + "datasets.html"); check("datasets page lists the new sets", p.locator("text=Democracy, human rights, press freedom and corruption").count() >= 1)
    p.goto(BASE + "updates.html"); p.wait_for_timeout(800); check("updates page loads", not [e for e in errs if "PAGEERROR" in e], errs[:3])
    check("other pages: no console errors", not errs, errs[:4]); c.close()
    c, p, errs = make(b, vp=(390, 800)); p.goto(BASE + "index.html"); p.wait_for_selector("#rows .ds"); p.wait_for_timeout(600)
    check("phone home: nothing overflows sideways", p.evaluate("document.documentElement.scrollWidth - innerWidth") <= 0, p.evaluate("document.documentElement.scrollWidth - innerWidth"))
    p.locator("#topics").scroll_into_view_if_needed(); shot(p, "home-topics-phone.png"); c.close()
    c, p, errs = make(b, vp=(1360, 900)); p.goto(BASE + "index.html"); p.wait_for_selector("#rows .ds"); p.wait_for_timeout(900); p.locator("#datasets").scroll_into_view_if_needed(); p.wait_for_timeout(400); shot(p, "home-topics-desk.png"); c.close()
    b.close()
print(f"\n{sum(res)} of {len(res)} checks passed"); sys.exit(0 if all(res) else 1)
